    },
    {
      "filename": "03 Scope.txt",
      "folder_structure": [
        "03 Scope"
      ],
      "file_description": "What is included in the specification, what is excluded, and the exact start and terminal boundaries of the process.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "04 Normative Language and Conventions.txt",
      "folder_structure": [
        "04 Normative Language and Conventions"
      ],
      "file_description": "Meaning of MUST, MUST NOT, SHOULD, MAY, PASS, FAIL, INVALID, PENDING, and other normative terms used by the specification.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "05 System Context.txt",
      "folder_structure": [
        "05 System Context"
      ],
      "file_description": "Where SBE sits relative to GeminiSupervisor, GeminiEvaluation, GitHub Actions, processing branches, main, and connected runtime components.",
