    },
    {
      "filename": "07 Trust and Security Model.txt",
      "folder_structure": [
        "07 Trust and Security Model"
      ],
      "file_description": "Trusted and untrusted components, secrecy boundary, threat model, encryption boundary, branch lifecycle assumptions, and what information may or may not be exposed.",
