    },
    {
      "filename": "10 Inputs.txt",
      "folder_structure": [
        "10 Inputs"
      ],
      "file_description": "Initial nextmessage/task input, authoritative request, request_id, completion criteria, submission artifact, PR metadata, source SHA, nonce, and all other process inputs.",
