    },
    {
      "filename": "11 Outputs.txt",
      "folder_structure": [
        "11 Outputs"
      ],
      "file_description": "Sealed submission archive, delete marker, manifest fields, evaluator answer archive, final evaluation archive, workflow outputs, terminal status, and observable repository state.",
