    },
    {
      "filename": "12 Persistent Artifacts and Storage Locations.txt",
      "folder_structure": [
        "12 Persistent Artifacts and Storage Locations"
      ],
      "file_description": "Canonical paths on main, temporary paths, processing-branch paths, encrypted artifacts, manifests, request files, and any lifecycle rules for each artifact.",
