    },
    {
      "filename": "13 End-to-End Process Overview.txt",
      "folder_structure": [
        "13 End-to-End Process Overview"
      ],
      "file_description": "High-level ordered flow from initial nextmessage through request creation, processing branch, sealing, deletion, evaluation, validation, persistence, and terminal PASS/FAIL.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "14 Detailed Processing Stages.txt",
      "folder_structure": [
        "14 Detailed Processing Stages"
      ],
      "file_description": "Detailed ordered stages from initial nextmessage ingestion through terminal PASS/FAIL determination.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
