    {
      "filename": "15 State Model.txt",
      "folder_structure": [
        "15 State Model"
      ],
      "file_description": "Complete set of named process states, including initial, pending, sealed, branch-deleted, evaluating, invalid-return, repaired, PASS, FAIL, and infrastructure-error states where applicable.",
