    },
    {
      "filename": "16 State Transition Specification.txt",
      "folder_structure": [
        "16 State Transition Specification"
      ],
      "file_description": "For every state: triggering event, required preconditions, transition guard, action performed, outputs produced, next state, and forbidden transitions.",
