    },
    {
      "filename": "17 Workflow, Job, Step, and Function Mapping.txt",
      "folder_structure": [
        "17 Workflow, Job, Step, and Function Mapping"
      ],
      "file_description": "Exact GitHub workflow files, jobs, workflow steps, JavaScript functions, shell blocks, and their role in the state machine.",
