    },
    {
      "filename": "18 Data Contracts and Schemas.txt",
      "folder_structure": [
        "18 Data Contracts and Schemas"
      ],
      "file_description": "Request JSON schema, marker schema, manifest schema, evaluator answer schema, validation-result schema, archive contents, and any exact-key/order requirements.",
