    },
    {
      "filename": "19 Validation and Gate Conditions.txt",
      "folder_structure": [
        "19 Validation and Gate Conditions"
      ],
      "file_description": "Deterministic checks performed at each stage, what constitutes a valid result, which checks are blocking, and how validation results control continuation.",
