    },
    {
      "filename": "20 PASS-FAIL Semantics.txt",
      "folder_structure": [
        "20 PASS-FAIL Semantics"
      ],
      "file_description": "Exact definition of SBE PASS, exact definition of SBE FAIL, distinction between schema failure and substantive evaluation failure, and terminal-state authority.",
