    },
    {
      "filename": "22 Retry and Repair Behavior.txt",
      "folder_structure": [
        "22 Retry and Repair Behavior"
      ],
      "file_description": "Which operations may retry, maximum attempt counts, sequencing, repair payload requirements, and conditions that terminate retries.",
