    },
    {
      "filename": "23 Idempotency and Re-entrancy.txt",
      "folder_structure": [
        "23 Idempotency and Re-entrancy"
      ],
      "file_description": "Expected behavior when workflows or stages are repeated, resumed, re-triggered, or partially completed.",
