    },
    {
      "filename": "24 Invariants.txt",
      "folder_structure": [
        "24 Invariants"
      ],
      "file_description": "Conditions that must remain true throughout the process, such as no plaintext merge to main, no evaluation before branch deletion, nonce consistency, exact artifact location, and controller ownership of privileged writes.",
