    },
    {
      "filename": "25 Ordering Constraints.txt",
      "folder_structure": [
        "25 Ordering Constraints"
      ],
      "file_description": "Required temporal sequence and explicitly prohibited reorderings between sealing, persistence, branch deletion, nonce generation, evaluation, validation, and final persistence.",
