    },
    {
      "filename": "26 Interface Boundaries.txt",
      "folder_structure": [
        "26 Interface Boundaries"
      ],
      "file_description": "Inputs and outputs between agent, workflow, evaluator, Gemini API, git/GitHub, archive tooling, and persistent storage.",
