    },
    {
      "filename": "27 Evidence and Observability.txt",
      "folder_structure": [
        "27 Evidence and Observability"
      ],
      "file_description": "Which repository objects, workflow results, manifests, artifacts, logs, and API results constitute authoritative evidence for each material state claim.",
