    },
    {
      "filename": "29 Verification Procedure.txt",
      "folder_structure": [
        "29 Verification Procedure"
      ],
      "file_description": "Deterministic method for independently confirming folders, branches, PR state, artifacts, manifest fields, workflow conclusions, nonce association, and final PASS/FAIL.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "30 Test Plan.txt",

"folder_structure": [
        "30 Test Plan"
      ],
      "file_description": "Unit, integration, negative, malformed-return, nonce-mismatch, archive-integrity, branch-lifecycle, retry, and full end-to-end smoke tests.",
