    },
    {
      "filename": "31 Failure Scenarios and Expected Outcomes.txt",
      "folder_structure": [
        "31 Failure Scenarios and Expected Outcomes"
      ],
      "file_description": "Representative failure cases and the required resulting state, exit code, workflow conclusion, persisted evidence, and allowed next action.",
