    },
    {
      "filename": "32 Traceability Matrix.txt",
      "folder_structure": [
        "32 Traceability Matrix"
      ],
      "file_description": "Mapping from requirements and invariants to workflows, functions, validation checks, artifacts, tests, and evidence sources.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "33 Operational Procedures.txt",
      "folder_structure": [
        "33 Operational Procedures"
      ],
      "file_description": "How to initiate an SBE run, observe progress, diagnose failure, recover safely, and determine whether manual intervention is permitted.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "34 Change-Control Requirements.txt",
      "folder_structure": [
        "34 Change-Control Requirements"
      ],
      "file_description": "Rules for changing schemas, workflows, scripts, ordering, secrets, state transitions, or completion semantics without silently breaking the protocol.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "35 Known Limitations and Non-Goals.txt",
      "folder_structure": [
        "35 Known Limitations and Non-Goals"
      ],
      "file_description": "Explicitly documented implementation limits, unsupported behaviors, assumptions, and concerns intentionally outside SBE scope.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "36 Glossary.txt",
      "folder_structure": [
        "36 Glossary"
      ],
      "file_description": "Definitions of SBE-specific terms, state names, artifact names, role names, and status vocabulary.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    },
    {
      "filename": "37 Appendices.txt",
      "folder_structure": [
        "37 Appendices"
      ],
      "file_description": "Canonical repository paths, exact schemas and examples, state-transition table, sequence representation, workflow/function index, validation/exit-code table, and reference evidence locations.",
      "last_commit": "7f11dc18ab4e65bf470712701ea3c99de427e6a6"
    }
  ]
